head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > P > longdesc]<br/>Image 컴포넌트 이미지의 상세 설명 페이지를 URL 로 설정합니다.",
    "validation" : [
        "문자열 값 설정 시, Image 컴포넌트에 로드된 이미지의 상세 설명 페이지를 URL 로 설정합니다.",
        "문자열 값 설정 시, 이미지에 대한 자세한 설명이 담긴 별도의 페이지나 리소스 URL 을 설정합니다.",
        "하위 버전 호환을 위한 속성이며 HTML5 에서 지원하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 초기값 설정 (longdesc : 별도 페이지 URL)
    con_longdesc.setValue("/sample/image/image_longdesc.html");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cLongdesc = con_longdesc.getValue();

    let lblLongdesc = (cLongdesc === '') ? '미설정' : cLongdesc;

    $c.gcm.createLabel('label="[현재] longdesc = ' + lblLongdesc + '\n[절차] con 값 변경 -> Target 재생성 -> longdesc 확인 버튼 클릭\n[확인] longdesc 는 마크업 속성으로만 남고 렌더링 등 브라우저 동작에는 전혀 반영되지 않는지 확인합니다"', '', 'label1');

    // 조건 설정
    let properties = {
        longdesc : cLongdesc,
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicImage(cList, '');
}



// validation 항목별 판정 출력
scwin.btn_checkLongdesc_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    let img = target1.render;

    let ldAttr = img.getAttribute("longdesc");

    let strLd = (ldAttr === null) ? "없음" : "'" + ldAttr + "'";

    // 항목 2 : 설정한 URL 이 이미지 리소스(src) 와는 다른 별도의 페이지 / 리소스를 가리키는지 절대경로로 해석하여 대비한다
    let strAbs = (ldAttr === null || ldAttr === "") ? "없음" : new URL(ldAttr, location.href).href;

    // 항목 3 : 마크업에는 longdesc 가 남지만 HTML5 미지원이라 렌더 결과(크기 / 상세 설명 UI 노드)에는 아무 영향이 없다
    let rect  = img.getBoundingClientRect();
    let strBox = Math.round(rect.width) + "x" + Math.round(rect.height);
    let ldUiCnt = img.parentElement.querySelectorAll("a, [role='link'], [class*='longdesc']").length;

    bottom.setReturnValue("[1] longdesc 속성값 : " + strLd);
    bottom.setReturnValue("[2] 상세 설명 URL(절대경로) : " + strAbs + " / 이미지 src : " + img.src);
    bottom.setReturnValue("[3] 마크업 longdesc 속성 : " + img.hasAttribute("longdesc") + " / 렌더 결과 : " + strBox + ", 상세 설명 UI 노드 " + ldUiCnt + "개 (HTML5 미지원으로 렌더링 반영 없음)");
};
